Given an array of positive numbers, calculate the number of possible contiguous subarrays having product lesser than a given number k.Input : arr[] = [1, 2, 3, 4] , k = 10Output : 7Explanation: The subarrays are [1], [2], [3], [4], [1, 2], [1, 2, 3] and [2, 3]Input  : arr[] = [1, 9, 2, 8, 6, 4, 3], k = 100Output : 16Input  : arr[] = [10, 5, 2, 6] , k = 100Output : 8Try It YourselfTable of Content[Naive Approach] Sliding Window with Product - O(n²) Time and O(1) Space[Expected Approach] Using Sliding Window Approach - O(n) time and O(1) space[Naive Approach] Sliding Window with Product - O(n²) Time and O(1) SpaceCount all subarrays whose product is less than k. For each starting index, extend window to the right while product remains < k. Once product exceeds k, break for that starting index.Initialize count = 0.For i from 0 to n-1: Set product = arr[i] and If product < k, increment count.For j from i+1 to n-1: Multiply product by arr[j]. If product < k, increment count. Else break inner loop.Return count.
            C++

    #include <iostream>
#include <vector>

using namespace std;

int countSubarray(vector<int>& arr, int k)
{
    int count = 0;

    for (int i = 0; i < arr.size(); i++)
    {
        long long product = arr[i];

        // Single-element subarray
        if (product < k)
            count++;

        // Extend the subarray
        for (int j = i + 1; j < arr.size(); j++)
        {
            product *= arr[j];

            // Count the subarray if product is less than k
            if (product < k)
                count++;
            else
                break;
        }
    }

    return count;
}

int main()
{
    vector<int> arr = {1, 2, 3, 4};
    int k = 10;

    cout << countSubarray(arr, k) << "\n";

    return 0;
}


