[Expected Approach] Using Sliding Window Approach - O(n) time and O(1) spaceMaintain a sliding window where the product of all elements inside is always less than k. For each position as window end, the number of valid subarrays ending at that position equals the current window length. Expand window by moving end, shrink from start if product becomes ≥ k.Initialize product = 1, count = 0, start = 0Iterate end from 0 to n-1Multiply product by arr[end]While product ≥ k and start ≤ end, divide product by arr[start] and increment startAdd (end - start + 1) to countReturn count
            C++

    #include <iostream>
#include <vector>

using namespace std;

int countSubarray(const vector<int>& arr, int k)
{
    int n = arr.size();

    long long product = 1;
    int count = 0;

    for (int start = 0, end = 0; end < n; end++)
    {
        // Add current element to the window product
        product *= arr[end];

        // Shrink the window until product becomes less than k
        while (start <= end && product >= k)
        {
            product /= arr[start];
            start++;
        }

        // Count all valid subarrays ending at 'end'
        count += (end - start + 1);
    }

    return count;
}

int main()
{
    vector<int> arr = {1, 2, 3, 4};
    int k = 10;

    cout << countSubarray(arr, k) ;


    return 0;
}


